const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sectorPhotos={"Seguridad y vigilancia":"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=600&q=80","Turismo y recreación":"https://images.unsplash.com/photo-1542744173-8e7e53415bb0?w=600&q=80","Educación y servicios":"https://images.unsplash.com/photo-1521791136064-7986c2920216?w=600&q=80","Automotriz y mecánica":"https://images.unsplash.com/photo-1581578731548-c64695cc6952?w=600&q=80","Energía y medio ambiente":"https://images.unsplash.com/photo-1581092921461-eab62e97a780?w=600&q=80","Administración y oficinas":"https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=600&q=80","Comercio y ventas":"https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=600&q=80","Limpieza y mantenimiento":"https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=600&q=80","Salud":"https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=600&q=80","Tecnología y sistemas":"https://images.unsplash.com/photo-1497366811353-6870744d04b2?w=600&q=80","Construcción": "https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=600&q=80", "Hotelería": "https://images.unsplash.com/photo-1566073771259-6a8506099945?w=600&q=80", "Gastronomía": "https://images.unsplash.com/photo-1556911220-bff31c812dba?w=600&q=80", "Logística": "https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?w=600&q=80", "Industria": "https://images.unsplash.com/photo-1565514020179-026b92b84bb6?w=600&q=80", "Agricultura": "https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=600&q=80", "Transporte": "https://images.unsplash.com/photo-1519003722824-194d4455a60c?w=600&q=80", "Cuidados": "https://images.unsplash.com/photo-1576765607924-bab6caa8c4c8?w=600&q=80"};
const sectorIcons={'Construcción':'▥','Hotelería':'♜','Gastronomía':'♨','Logística':'▣','Industria':'⚙','Agricultura':'❀','Transporte':'➜','Cuidados':'♡','Tecnología y sistemas':'⌘','Salud':'✚','Limpieza y mantenimiento':'✧','Comercio y ventas':'◇','Administración y oficinas':'▤','Energía y medio ambiente':'☼','Automotriz y mecánica':'⚙','Educación y servicios':'✎','Turismo y recreación':'✈','Seguridad y vigilancia':'⬡'};
const serviceIcons={'Turismo':'✈','Trabajo':'▣','Estudios':'✎','Familia':'♡','Residencia':'⌂','Documentación':'▤','Orientación':'◈','Empresas':'▥','Trámites consulares':'◎','Regularización':'◉'};
function render(){const q=keyword.value.toLocaleLowerCase().trim(),c=country.value;
 document.querySelector('#sectorControls').innerHTML=sectorNames.map(t=>`<button class="sector-btn ${activeSector===t?'active':''}" data-sector="${esc(t)}"><span class="sector-mark" aria-hidden="true">${sectorIcons[t]||"◈"}</span><span>${esc(t)} <small>Explorar ↗</small></span></button>`).join('');
 document.querySelectorAll('[data-sector]').forEach(b=>b.onclick=()=>{activeSector=b.dataset.sector;render();document.querySelector('#jobs').scrollIntoView({behavior:'smooth',block:'start'})});
 let list=jobs.filter(j=>(!activeSector||j.sector===activeSector)&&(!c||j.countries.includes(c))&&(!q||(j.title+' '+j.sector+' '+j.desc).toLocaleLowerCase().includes(q)));
 document.querySelector('#empty').style.display=list.length||(!activeSector&&!q&&!c)?'none':'block';
 if(!activeSector&&!q&&!c){grid.innerHTML='<div class="sector-heading">Selecciona un sector para descubrir las oportunidades</div>';return}
 const groups=[...new Set(list.map(j=>j.sector))];
 grid.innerHTML=groups.map(g=>`<h3 class="sector-heading">${esc(g)} · Oportunidades laborales</h3>`+list.filter(j=>j.sector===g).map(j=>`<article class="job" data-job-card="${jobs.indexOf(j)}" tabindex="0" role="button" aria-label="Ver detalles de ${esc(j.title)}"><div class="profession-mark" aria-hidden="true"><span>${sectorIcons[j.sector]||"◈"}</span><small>${esc(j.sector)}</small></div><div class="job-body"><span class="tag">${esc(j.countries.join(' · '))}</span><h3>${esc(j.title)}</h3><p>${esc(j.desc)}</p><p class="job-detail"><b>Requisitos:</b> ${esc(j.requirements[0])}</p><p class="job-detail"><b>Prestaciones:</b> Conforme al contrato y legislación del destino</p><div class="job-bottom"><small>Actividades · Requisitos · Prestaciones</small><button data-job="${jobs.indexOf(j)}">Ver vacante ↗</button></div></div></article>`).join('')).join('');
 grid.querySelectorAll('[data-job-card]').forEach(card=>{const open=()=>showJob(jobs[Number(card.dataset.jobCard)]);card.onclick=open;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});grid.querySelectorAll('[data-job]').forEach(b=>b.onclick=e=>{e.stopPropagation();showJob(jobs[Number(b.dataset.job)])});}
function section(title,arr,ordered=false){return `<section class="detail-section"><h3>${esc(title)}</h3><${ordered?'ol':'ul'}>${arr.map(x=>`<li>${esc(x)}</li>`).join('')}</${ordered?'ol':'ul'}></section>`}
function openModal(title,html,tag='FINEN',note=''){document.querySelector('#modalTitle').textContent=title;document.querySelector('#modalText').innerHTML=html;document.querySelector('#modalTag').textContent=tag;document.querySelector('#modalNote').textContent=note;document.querySelector('#modal').classList.add('open');document.querySelector('.dialog').scrollTop=0;}
function showJob(j){openModal(j.title,`<div class="modal-profession"><span aria-hidden="true">${sectorIcons[j.sector]||"◈"}</span><strong>${esc(j.sector)}</strong></div><div class="detail-dest">📍 Destinos: ${esc(j.countries.join(' · '))}</div><p class="detail-lead">${esc(j.desc)}</p>${section('Actividades a realizar',j.activities)}${section('Requisitos del puesto',j.requirements)}${section('Prestaciones y condiciones',j.benefits)}<button class="detail-cta" id="requestJob">Solicitar información sobre esta vacante ↗</button>`,j.sector,'La elegibilidad, el salario y las prestaciones específicas se confirman durante la atención según el empleador y el contrato.');document.querySelector('#requestJob').onclick=()=>requestInfo('Vacante: '+j.title)}
function renderServices(){
 const q=(document.querySelector('#serviceSearch')?.value||'').toLocaleLowerCase().trim();
 const cats=[...new Set(services.map(x=>x.category))];
 const visible=services.filter(x=>(activeService==='Todos'||x.category===activeService)&&(!q||(x.title+' '+x.category+' '+x.desc+' '+x.dest).toLocaleLowerCase().includes(q)));
 const catalog=document.querySelector('#serviceCatalog');
 const controls=document.querySelector('#serviceFilters');
 if(activeService==='Todos'&&!q){
   controls.innerHTML='';
   catalog.classList.add('service-sectors-mode');
   catalog.innerHTML=cats.map((cat,i)=>{const first=services.find(x=>x.category===cat);const photo=first?.photo||'';return `<button type="button" class="service-sector-tile" data-open-cat="${esc(cat)}" aria-label="Explorar ${esc(cat)}"><span class="service-sector-symbol" aria-hidden="true">${serviceIcons[cat]||"✦"}</span><span class="service-sector-shade"></span><span class="service-sector-content"><small>ÁREA DE ATENCIÓN</small><strong>${esc(cat)}</strong><em>Explorar servicios <span aria-hidden="true">↗</span></em></span></button>`}).join('');
   catalog.querySelectorAll('[data-open-cat]').forEach(btn=>btn.onclick=()=>{activeService=btn.dataset.openCat;renderServices();document.querySelector('#serviceCatalog').scrollIntoView({behavior:'smooth',block:'start'})});
   return;
 }
 catalog.classList.remove('service-sectors-mode');
 controls.innerHTML=`<button type="button" class="service-filter back-services" id="allServiceCategories">← Ver todas las áreas</button>`;
 document.querySelector('#allServiceCategories').onclick=()=>{activeService='Todos';const input=document.querySelector('#serviceSearch');if(input)input.value='';renderServices()};
 const groups=[...new Set(visible.map(x=>x.category))];
 catalog.innerHTML=visible.length?groups.map(g=>`<h3 class="service-heading">${esc(g)}</h3>`+visible.filter(x=>x.category===g).map(x=>`<article class="svc-card"><div class="service-card-symbol" aria-hidden="true">${serviceIcons[x.category]||"✦"}</div><div class="svc-content"><h3>${esc(x.title)}</h3><span class="svc-dest">${esc(x.dest)}</span><p>${esc(x.desc)}</p><button data-svc="${services.indexOf(x)}">Ver requisitos y proceso ↗</button></div></article>`).join('')).join(''):'<p class="empty" style="display:block">No encontramos un servicio con ese nombre. Prueba otra búsqueda.</p>';
 catalog.querySelectorAll('[data-svc]').forEach(b=>b.onclick=()=>showService(services[Number(b.dataset.svc)]));
}
function showService(x){
 const steps=x.steps.map((v,i)=>`<div class="service-step"><b>${i+1}</b><span>${esc(v)}</span></div>`).join('');
 const requirements=x.requirements.map(v=>`<li>${esc(v)}</li>`).join('');
 const content=`<div class="service-detail-identity"><span aria-hidden="true">${serviceIcons[x.category]||"✦"}</span><strong>${esc(x.category)}</strong></div><p class="detail-lead">${esc(x.desc)}</p><div class="service-overview"><div><small>Destinos de atención</small><strong>${esc(x.dest)}</strong></div><div><small>Tipo de atención</small><strong>Asesoría y preparación documental</strong></div></div><h3 class="service-detail-subhead">Documentos que se revisan para este servicio</h3><ul class="service-document-list">${requirements}</ul><h3 class="service-detail-subhead">Cómo funciona la atención</h3><div class="service-detail-steps">${steps}</div><p class="service-notice">Los requisitos, costos oficiales y decisiones migratorias dependen de la autoridad correspondiente y de tu situación particular.</p><div class="service-detail-actions"><button id="requestService">Solicitar asesoría sobre este trámite →</button><button class="secondary-action" id="backServices">Ver otros servicios</button></div>`;
 openModal(x.title,content,x.category,'');
 document.querySelector('#requestService').onclick=()=>requestInfo('Servicio: '+x.title);
 document.querySelector('#backServices').onclick=()=>{document.querySelector('#modal').classList.remove('open');document.querySelector('#catalogo-servicios').scrollIntoView({behavior:'smooth'})};
}
function requestInfo(subject){
 const type=subject.startsWith('Vacante:')?'Postulación laboral':subject.startsWith('Servicio:')?'Solicitud de trámite':'Solicitud de información';
 const fields=`<p class="form-intro">Completa tus datos para preparar tu solicitud de atención. <strong>${esc(subject)}</strong></p><form id="requestForm" class="request-form"><input type="hidden" name="interes" value="${esc(subject)}"><input type="hidden" name="tipo" value="${esc(type)}"><label>Nombre completo<input name="nombre" autocomplete="name" required maxlength="120" placeholder="Nombre y apellidos"></label><label>Teléfono de contacto<input name="telefono" type="tel" autocomplete="tel" required minlength="10" maxlength="20" placeholder="10 dígitos"></label><label>Correo electrónico<input name="correo" type="email" autocomplete="email" required placeholder="correo@ejemplo.com"></label><label>País de interés<select name="destino" required><option value="">Selecciona un país</option><option>Estados Unidos</option><option>Canadá</option><option>Europa</option><option>Indistinto</option></select></label><label>Estado o ciudad de residencia<input name="ciudad" required maxlength="90" placeholder="Tu ciudad actual"></label><label>Experiencia o situación actual<select name="experiencia" required><option value="">Selecciona una opción</option><option>Sin experiencia previa</option><option>Menos de 1 año</option><option>1 a 3 años</option><option>Más de 3 años</option><option>No aplica a mi trámite</option></select></label><label class="full">Cuéntanos qué necesitas<textarea name="comentarios" rows="3" maxlength="800" placeholder="Cuéntanos brevemente sobre tu interés"></textarea></label><label class="check full"><input type="checkbox" name="acepto" required>Confirmo que los datos son correctos y he leído la información sobre privacidad.</label><button type="submit">Preparar mi solicitud →</button></form><div id="requestFeedback" aria-live="polite"></div>`;
 openModal(type,fields,'Atención FINEN','');
 document.querySelector('#requestForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form).entries());delete data.acepto;data.fecha=new Date().toISOString();const feedback=document.querySelector('#requestFeedback');const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{if(location.hostname.endsWith('.netlify.app')||document.documentElement.dataset.netlify==='true'){const params=new URLSearchParams({...data,'form-name':'finen-solicitudes'});const response=await fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:params.toString()});if(!response.ok)throw Error('No se pudo enviar');feedback.innerHTML='<div class="form-feedback">Tu solicitud se ha enviado correctamente.</div>';form.reset();}else{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='FINEN-solicitud.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);feedback.innerHTML='<div class="form-feedback">Se descargó tu solicitud para conservarla. Este archivo no envía datos a FINEN: la recepción en línea se habilita al publicar el sitio con el formulario conectado.</div>';}}catch(err){feedback.innerHTML='<div class="form-feedback">No fue posible enviar la solicitud. Inténtalo de nuevo más tarde.</div>'}finally{submit.disabled=false}};
}
document.querySelector('#searchForm').onsubmit=e=>{e.preventDefault();activeSector=null;render();document.querySelector('#vacantes').scrollIntoView({behavior:'smooth'})};document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>{keyword.value=b.dataset.search;country.value='';activeSector=null;render();document.querySelector('#vacantes').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-dest]').forEach(a=>a.onclick=()=>{country.value=a.dataset.dest;keyword.value='';activeSector=null;render()});
document.querySelector('#contactBtn').onclick=()=>requestInfo('Orientación migratoria o laboral');document.querySelector('#close').onclick=document.querySelector('#modalOk').onclick=()=>document.querySelector('#modal').classList.remove('open');document.querySelector('#modal').onclick=e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')};document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('#modal').classList.remove('open')});document.querySelector('#menu').onclick=()=>document.querySelector('#menuPanel').classList.toggle('show');document.querySelectorAll('.menu-panel a').forEach(a=>a.onclick=()=>document.querySelector('#menuPanel').classList.remove('show'));
document.querySelector('#serviceSearch').addEventListener('input',renderServices);
document.querySelector('#servicesStart').onclick=()=>document.querySelector('.services-toolbar').scrollIntoView({behavior:'smooth',block:'start'});
jobs.forEach((j,i)=>{j.img='assets/profesiones/'+String(i+1).padStart(3,'0')+'.svg'});
render();renderServices();
